export interface IPhysics2DBackend {
    readonly name: string;
    step(dt: number): void;
    addRigidBody(entity: VectorEntity, options: Rigid2DOptions): RigidBody2DComponent;
    addSoftBody?(entity: VectorEntity, options: SoftBody2DOptions): SoftBody2DComponent;
    addJoint(options: Joint2DOptions): Joint2D;
    removeJoint(joint: Joint2D): void;
    getJoints?(): Joint2D[];
    remove(entity: VectorEntity): void;
    getBodyAtPoint?(point: {
        x: number;
        y: number;
    }): RigidBody2DComponent | null;
    onCollision?(callback: (event: Collision2DEvent) => void): void;
    createMouseJoint?(bodyComp: RigidBody2DComponent, target: {
        x: number;
        y: number;
    }, options?: MouseDragOptions): any;
    updateMouseJoint?(mouseJoint: any, target: {
        x: number;
        y: number;
    }): void;
    destroyMouseJoint?(mouseJoint: any): void;
    destroy(): void;
}

